#!/usr/bin/env node
/**
 * Generates robots.txt and sitemap.xml from data/seo.json.
 *
 * data/seo.json is the only place SEO is configured. This script never guesses:
 * if a club isn't listed there, it is not in the sitemap, and you get told about it.
 *
 *   npm run build:seo          write the files
 *   npm run build:seo -- --check   verify they're current, change nothing (exit 1 if stale)
 *
 * Commit the generated files. They're served as static assets.
 */

import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const CHECK = process.argv.includes("--check");

const seo = JSON.parse(readFileSync(join(ROOT, "data/seo.json"), "utf8"));
const roster = JSON.parse(readFileSync(join(ROOT, "data/clubs-map.json"), "utf8"));

const base = seo.site.baseUrl.replace(/\/$/, "");
const problems = [];
const notes = [];

/* ---------- validate against the live roster ---------- */

const rosterCities = new Set(roster.map((r) => r.city));
const seoCities = new Set(Object.keys(seo.clubs));

for (const city of rosterCities) {
  if (!seoCities.has(city)) {
    problems.push(`Club "${city}" is in clubs-map.json but missing from data/seo.json. Add it.`);
  }
}
for (const city of seoCities) {
  if (!rosterCities.has(city)) {
    problems.push(`Club "${city}" is in data/seo.json but no longer in clubs-map.json. Remove it.`);
  }
}

const slugs = new Map();
for (const [city, c] of Object.entries(seo.clubs)) {
  if (slugs.has(c.slug)) {
    problems.push(`Duplicate slug "${c.slug}" — used by "${city}" and "${slugs.get(c.slug)}".`);
  }
  slugs.set(c.slug, city);
}

/* ---------- pages ---------- */

const indexed = seo.pages.filter((p) => p.indexed);
const blocked = seo.pages.filter((p) => !p.indexed);

for (const p of seo.pages) {
  const file = p.path === "/" ? "index.html" : p.path.replace(/^\//, "");
  if (!existsSync(join(ROOT, file))) {
    problems.push(`Page "${p.path}" is listed in data/seo.json but ${file} does not exist.`);
  }
}

/* ---------- club pages ---------- */

const publishable = Object.entries(seo.clubs).filter(([, c]) => c.publish);
const thin = Object.entries(seo.clubs).filter(([, c]) => !c.publish);
let clubUrls = [];

if (seo.clubPages.enabled) {
  clubUrls = publishable.map(([, c]) => ({
    loc: base + seo.clubPages.urlPattern.replace("{slug}", c.slug),
    priority: c.priority,
    changefreq: "weekly",
  }));
  for (const [city, c] of publishable) {
    const file = c.slug + ".html";
    if (!existsSync(join(ROOT, file))) {
      problems.push(`clubPages.enabled is true but ${file} (for "${city}") does not exist — the sitemap would advertise a 404.`);
    }
  }
} else {
  notes.push(
    `clubPages.enabled is false — ${publishable.length} publish-ready city pages are NOT in the sitemap. ` +
      `Flip it in data/seo.json once the pages exist.`
  );
}

if (thin.length) {
  notes.push(
    `${thin.length} clubs held back as thin (no confirmed schedule and/or venue): ` +
      thin.map(([city]) => city).join(", ")
  );
}

/* ---------- emit ---------- */

const stamp = new Date().toISOString().slice(0, 10);

const robots = [
  "# Generated by scripts/build-seo.mjs from data/seo.json — do not edit by hand.",
  `# Last generated: ${stamp}`,
  "",
  "User-agent: *",
  ...blocked.map((p) => `Disallow: ${p.path}${p.noindexReason ? `   # ${p.noindexReason}` : ""}`),
  "Allow: /",
  "",
  `Sitemap: ${base}/sitemap.xml`,
  "",
].join("\n");

const urls = [
  ...indexed.map((p) => ({
    loc: base + (p.path === "/" ? "/" : p.path),
    priority: p.priority,
    changefreq: p.changefreq,
  })),
  ...clubUrls,
];

const sitemap = [
  '<?xml version="1.0" encoding="UTF-8"?>',
  "<!-- Generated by scripts/build-seo.mjs from data/seo.json — do not edit by hand. -->",
  '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">',
  ...urls.map((u) =>
    [
      "  <url>",
      `    <loc>${u.loc}</loc>`,
      `    <lastmod>${stamp}</lastmod>`,
      `    <changefreq>${u.changefreq}</changefreq>`,
      `    <priority>${u.priority.toFixed(1)}</priority>`,
      "  </url>",
    ].join("\n")
  ),
  "</urlset>",
  "",
].join("\n");

/* ---------- report ---------- */

const targets = [
  ["robots.txt", robots],
  ["sitemap.xml", sitemap],
];

if (problems.length) {
  console.error("\nSEO config problems:\n");
  for (const p of problems) console.error("  ✗ " + p);
  console.error("");
  process.exit(1);
}

let stale = false;
for (const [name, content] of targets) {
  const path = join(ROOT, name);
  const current = existsSync(path) ? readFileSync(path, "utf8") : null;
  // Ignore the date stamp when comparing, or --check fails every new day.
  const norm = (s) => (s || "").replace(/(Last generated: |<lastmod>)[\d-]+/g, "$1");
  if (norm(current) !== norm(content)) {
    stale = true;
    if (CHECK) console.error(`  ✗ ${name} is out of date — run \`npm run build:seo\``);
    else {
      writeFileSync(path, content);
      console.log(`  ✓ wrote ${name}`);
    }
  } else if (!CHECK) {
    console.log(`  · ${name} unchanged`);
  }
}

if (CHECK && stale) process.exit(1);
if (CHECK) console.log("  ✓ robots.txt and sitemap.xml are current");

console.log(`\n  ${indexed.length} pages indexed, ${blocked.length} blocked, ${urls.length} URLs in sitemap`);
for (const n of notes) console.log("  ! " + n);
console.log("");
